PRAGMA foreign_keys = ON;

CREATE TABLE schema_metadata (singleton INTEGER PRIMARY KEY CHECK(singleton=1), schema_version INTEGER NOT NULL CHECK(schema_version=1), product_line TEXT NOT NULL CHECK(product_line='vibecoder-0.0.1'));
INSERT INTO schema_metadata VALUES (1, 1, 'vibecoder-0.0.1');
CREATE TABLE installation (id TEXT PRIMARY KEY, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE github_identity (singleton INTEGER PRIMARY KEY CHECK(singleton=1), github_user_id INTEGER NOT NULL CHECK(github_user_id>0), login TEXT NOT NULL, credential_ref TEXT NOT NULL REFERENCES secret_metadata(id), status TEXT NOT NULL CHECK(status IN ('ONLINE','OFFLINE','AUTH_FAILED')), configured_at TEXT NOT NULL, checked_at TEXT NOT NULL, diagnosis_json TEXT NOT NULL DEFAULT '{}', consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK(consecutive_failures>=0), next_check_at TEXT);
CREATE TABLE secret_metadata (id TEXT PRIMARY KEY, kind TEXT NOT NULL, storage_ref TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor TEXT NOT NULL, operation TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, result TEXT NOT NULL, detail_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);

CREATE TABLE github_repositories (id TEXT PRIMARY KEY, github_id INTEGER NOT NULL UNIQUE CHECK(github_id>0), node_id TEXT UNIQUE, owner_login TEXT NOT NULL, name TEXT NOT NULL, canonical_name TEXT NOT NULL UNIQUE COLLATE NOCASE, default_branch TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, repository_id TEXT NOT NULL UNIQUE REFERENCES github_repositories(id), base_branch TEXT NOT NULL, remote_sha TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ENABLED','DISABLED','BLOCKED')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX project_name_lookup ON projects(name COLLATE NOCASE);
CREATE TABLE project_authorized_users (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, github_user_id INTEGER NOT NULL CHECK(github_user_id>0), login TEXT NOT NULL, authorized_at TEXT NOT NULL, authorized_by TEXT, PRIMARY KEY(project_id, github_user_id));
CREATE TRIGGER preserve_last_project_user BEFORE DELETE ON project_authorized_users WHEN (SELECT count(*) FROM project_authorized_users WHERE project_id=OLD.project_id)=1 BEGIN SELECT RAISE(ABORT, 'cannot remove last authorized user'); END;
CREATE TABLE project_registration_operations (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('PREPARING','COMPLETED','FAILED')), repository_snapshot_json TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), purpose TEXT NOT NULL, path TEXT NOT NULL UNIQUE, base_branch TEXT NOT NULL, base_sha TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);

CREATE TABLE plugins (id TEXT NOT NULL, version TEXT NOT NULL, provider TEXT NOT NULL, descriptor_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(id, version));
CREATE TABLE plugin_installations (id TEXT PRIMARY KEY, plugin_id TEXT NOT NULL, plugin_version TEXT NOT NULL, status TEXT NOT NULL, installation_path TEXT, digest TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(plugin_id,plugin_version) REFERENCES plugins(id,version));
CREATE TABLE workers (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, plugin_id TEXT NOT NULL, plugin_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('INSTALLING','AUTHENTICATION_REQUIRED','VERIFYING','READY','UNAVAILABLE','DISABLED','ERROR')), config_json TEXT NOT NULL DEFAULT '{}', storage_path TEXT NOT NULL UNIQUE, concurrency_limit INTEGER NOT NULL CHECK(concurrency_limit>0), active_executions INTEGER NOT NULL DEFAULT 0 CHECK(active_executions>=0 AND active_executions<=concurrency_limit), last_checked_at TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(plugin_id,plugin_version) REFERENCES plugins(id,version));
CREATE TABLE worker_capabilities (worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE, capability TEXT NOT NULL, verified_at TEXT NOT NULL, PRIMARY KEY(worker_id, capability));
CREATE TABLE worker_secret_references (worker_id TEXT NOT NULL REFERENCES workers(id) ON DELETE CASCADE, secret_id TEXT NOT NULL REFERENCES secret_metadata(id), purpose TEXT NOT NULL, PRIMARY KEY(worker_id, secret_id, purpose));
CREATE TABLE worker_probes (id TEXT PRIMARY KEY, worker_id TEXT NOT NULL REFERENCES workers(id), status TEXT NOT NULL, capabilities_json TEXT NOT NULL, error_category TEXT, checked_at TEXT NOT NULL);
CREATE TABLE worker_runtime_identities (worker_id TEXT PRIMARY KEY REFERENCES workers(id) ON DELETE CASCADE, unix_user TEXT NOT NULL UNIQUE, isolation_kind TEXT NOT NULL, verified_at TEXT NOT NULL);
CREATE TABLE worker_registration_operations (id TEXT PRIMARY KEY, worker_id TEXT REFERENCES workers(id), operation_key TEXT NOT NULL UNIQUE, phase TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('RUNNING','SUCCEEDED','FAILED')), error_category TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE worker_authentication_operations (id TEXT PRIMARY KEY, worker_id TEXT NOT NULL REFERENCES workers(id), status TEXT NOT NULL CHECK(status IN ('RUNNING','SUCCEEDED','FAILED','CANCELLED','INTERRUPTED')), public_json TEXT NOT NULL DEFAULT '{}', error_category TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);

CREATE TABLE agents (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL COLLATE NOCASE, role TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PROPOSED','ACTIVE','SUSPENDED','RETIRED')), active_revision INTEGER NOT NULL CHECK(active_revision>0), pinned_worker_id TEXT REFERENCES workers(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,name), UNIQUE(id,project_id));
CREATE TABLE agent_revisions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), revision INTEGER NOT NULL CHECK(revision>0), responsibilities_json TEXT NOT NULL, capabilities_json TEXT NOT NULL, restrictions_json TEXT NOT NULL, instructions TEXT NOT NULL, instructions_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(agent_id,revision));
CREATE TRIGGER immutable_agent_revisions_update BEFORE UPDATE ON agent_revisions BEGIN SELECT RAISE(ABORT,'agent revisions are immutable'); END;
CREATE TRIGGER immutable_agent_revisions_delete BEFORE DELETE ON agent_revisions BEGIN SELECT RAISE(ABORT,'agent revisions are immutable'); END;
CREATE TABLE agent_worker_bindings (agent_id TEXT PRIMARY KEY REFERENCES agents(id), worker_id TEXT NOT NULL REFERENCES workers(id), bound_at TEXT NOT NULL, bound_by TEXT NOT NULL);
CREATE TABLE provider_sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), agent_id TEXT NOT NULL, worker_id TEXT NOT NULL REFERENCES workers(id), workspace_id TEXT REFERENCES workspaces(id), purpose TEXT NOT NULL, context_hash TEXT NOT NULL, provider_reference TEXT, status TEXT NOT NULL, continuity_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id,worker_id), FOREIGN KEY(agent_id,project_id) REFERENCES agents(id,project_id));
CREATE TABLE provider_executions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, worker_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL CHECK(state IN ('PENDING','RUNNING','RECONCILING','FINISHED')), outcome TEXT CHECK(outcome IN ('SUCCEEDED','FAILED','UNKNOWN','CANCELLED','WAITING_AUTH','WAITING_QUOTA','UNSUPPORTED')), provider_reference TEXT, error_category TEXT, result_json TEXT NOT NULL DEFAULT '{}', reconciliation_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((state='FINISHED')=(outcome IS NOT NULL)), FOREIGN KEY(session_id,worker_id) REFERENCES provider_sessions(id,worker_id));
CREATE TABLE runtime_approval_requests (id TEXT PRIMARY KEY, worker_id TEXT NOT NULL REFERENCES workers(id), session_id TEXT NOT NULL REFERENCES provider_sessions(id), execution_id TEXT NOT NULL REFERENCES provider_executions(id), provider_request_ref TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('COMMAND','FILE_CHANGE','PERMISSIONS')), summary TEXT NOT NULL, details_json TEXT NOT NULL, allowed_decisions_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','DECISION_RECORDED','DELIVERING','APPROVED','DENIED','EXPIRED','UNKNOWN')), decision TEXT CHECK(decision IN ('APPROVE','DENY')), actor TEXT, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, decided_at TEXT, delivered_at TEXT, resolved_at TEXT, diagnostic TEXT, UNIQUE(worker_id,execution_id,provider_request_ref));
CREATE INDEX runtime_approval_pending ON runtime_approval_requests(status,created_at);

CREATE TABLE issue_workflows (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), github_issue_id INTEGER NOT NULL, issue_number INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,github_issue_id));
CREATE TABLE authorized_messages (id TEXT PRIMARY KEY, issue_id TEXT REFERENCES issue_workflows(id), remote_kind TEXT NOT NULL, remote_id TEXT NOT NULL, author_github_id INTEGER NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(remote_kind,remote_id));
CREATE TABLE discarded_events (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), remote_kind TEXT NOT NULL, remote_id TEXT NOT NULL, author_github_id INTEGER, remote_created_at TEXT NOT NULL, discard_reason TEXT NOT NULL, UNIQUE(remote_kind,remote_id));
CREATE TABLE plan_revisions (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issue_workflows(id), revision INTEGER NOT NULL CHECK(revision>0), status TEXT NOT NULL, canonical_hash TEXT NOT NULL, plan_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(issue_id,revision), UNIQUE(issue_id,canonical_hash));
CREATE TRIGGER immutable_plan_update BEFORE UPDATE ON plan_revisions BEGIN SELECT RAISE(ABORT,'plan revisions are immutable'); END;
CREATE TRIGGER immutable_plan_delete BEFORE DELETE ON plan_revisions BEGIN SELECT RAISE(ABORT,'plan revisions are immutable'); END;
CREATE TABLE approvals (id TEXT PRIMARY KEY, plan_revision_id TEXT NOT NULL UNIQUE REFERENCES plan_revisions(id), plan_hash TEXT NOT NULL, approver_github_id INTEGER NOT NULL, remote_event_id TEXT NOT NULL UNIQUE, approved_at TEXT NOT NULL);
CREATE TRIGGER approval_hash_matches BEFORE INSERT ON approvals WHEN NEW.plan_hash<>(SELECT canonical_hash FROM plan_revisions WHERE id=NEW.plan_revision_id) BEGIN SELECT RAISE(ABORT,'approval hash does not match plan revision'); END;
CREATE TABLE tasks (id TEXT PRIMARY KEY, plan_revision_id TEXT NOT NULL REFERENCES plan_revisions(id), logical_id TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), description TEXT NOT NULL, acceptance_json TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(plan_revision_id,logical_id));
CREATE TABLE task_dependencies (task_id TEXT NOT NULL REFERENCES tasks(id), depends_on_task_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_task_id), CHECK(task_id<>depends_on_task_id));
CREATE TABLE pull_requests (id TEXT PRIMARY KEY, task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id), github_pr_id INTEGER NOT NULL, number INTEGER NOT NULL, head_ref TEXT NOT NULL, base_ref TEXT NOT NULL, head_sha TEXT NOT NULL, status TEXT NOT NULL, merge_commit_sha TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE review_events (id TEXT PRIMARY KEY, pull_request_id TEXT NOT NULL REFERENCES pull_requests(id), remote_kind TEXT NOT NULL, remote_id TEXT NOT NULL, author_github_id INTEGER NOT NULL, body TEXT NOT NULL, state TEXT, created_at TEXT NOT NULL, UNIQUE(remote_kind,remote_id));
CREATE TABLE corrections (id TEXT PRIMARY KEY, pull_request_id TEXT NOT NULL REFERENCES pull_requests(id), source_review_id TEXT NOT NULL REFERENCES review_events(id), scope TEXT NOT NULL, status TEXT NOT NULL, previous_sha TEXT NOT NULL, new_sha TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source_review_id));
CREATE TABLE verified_merges (id TEXT PRIMARY KEY, pull_request_id TEXT NOT NULL UNIQUE REFERENCES pull_requests(id), merge_commit_sha TEXT NOT NULL, method TEXT, verified_at TEXT NOT NULL);
CREATE TABLE workflow_publications (id TEXT PRIMARY KEY, plan_revision_id TEXT NOT NULL UNIQUE REFERENCES plan_revisions(id), external_operation_id TEXT NOT NULL UNIQUE, github_comment_id INTEGER, status TEXT NOT NULL CHECK(status IN ('INTENDED','SUCCEEDED','UNKNOWN','FAILED')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE task_runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), workspace_id TEXT REFERENCES workspaces(id), session_id TEXT REFERENCES provider_sessions(id), execution_id TEXT REFERENCES provider_executions(id), branch_name TEXT NOT NULL, base_sha TEXT NOT NULL, result_sha TEXT, status TEXT NOT NULL CHECK(status IN ('PREPARING','RUNNING','SUCCEEDED','FAILED','UNKNOWN')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(task_id));
CREATE TABLE workflow_cursors (project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE, last_poll_at TEXT, last_success_at TEXT, last_error TEXT, updated_at TEXT NOT NULL);

CREATE TABLE external_operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, payload_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('INTENDED','RUNNING','SUCCEEDED','FAILED','UNKNOWN','CANCELLED')), remote_reference TEXT, reconciliation_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE scheduled_jobs (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), kind TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, state TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, eligible_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, operation_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX scheduled_jobs_ready ON scheduled_jobs(state,eligible_at,priority);
CREATE TABLE job_leases (job_id TEXT PRIMARY KEY REFERENCES scheduled_jobs(id), runner_id TEXT NOT NULL, lease_token TEXT NOT NULL UNIQUE, acquired_at TEXT NOT NULL, heartbeat_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE operational_pauses (id TEXT PRIMARY KEY, scope_type TEXT NOT NULL, scope_id TEXT, kind TEXT NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, released_at TEXT);
CREATE TABLE recovery_barriers (id TEXT PRIMARY KEY, reason TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, cleared_at TEXT, cleared_by TEXT);
CREATE TABLE maintenance_journals (id TEXT PRIMARY KEY, operation_type TEXT NOT NULL, phase TEXT NOT NULL, status TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
